from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from oscar.core.loading import get_model

Basket = get_model('basket', 'Basket')
OrderCreator = get_model('order', 'OrderCreator')

class HeadlessCheckoutPlaceOrderView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        basket_id = request.data.get('basket_id')
        shipping_address_id = request.data.get('shipping_address_id')

        # Enforce that the basket belongs to the authenticated customer
        try:
            basket = Basket.objects.get(pk=basket_id, owner=request.user, status=Basket.OPEN)
        except Basket.DoesNotExist:
            return Response({'error': 'Active basket not found'}, status=status.HTTP_404_NOT_FOUND)

        order_creator = OrderCreator()
        order = order_creator.place_order(
            user=request.user,
            basket=basket,
            shipping_address_id=shipping_address_id
        )
        return Response({'order_number': order.number, 'status': 'placed'})
